import { test } from 'node:test';
import assert from 'node:assert/strict';
import { createState, frame } from '../game/neon.js';

const mockCtx = {
  fillRect: () => {},
  arc: () => {},
  fill: () => {},
  fillText: () => {},
  beginPath: () => {},
};

test('Brick collision: ball should bounce off top of brick', () => {
  const state = createState(1);
  // Position ball so it's colliding with the first brick from above
  // Brick 0: x=offsetX, y=BRICK_TOP, w=BRICK_W, h=BRICK_H
  // Let's just place it manually.
  const brick = state.bricks[0];
  state.ball = {
    x: brick.x + brick.w / 2,
    y: brick.y - 2, // Just above/overlapping the top
    r: 7,
    vx: 0,
    vy: 200, // Moving DOWN into the brick
  };

  const initialVy = state.ball.vy;
  frame(mockCtx, state);

  assert.ok(state.ball.vy < 0, `Ball should bounce UP (vy < 0), but got ${state.ball.vy}`);
});

test('Brick collision: ball should bounce off side of brick', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  state.ball = {
    x: brick.x - 2, // Just left/overlapping the left side
    y: brick.y + brick.h / 2,
    r: 7,
    vx: 200, // Moving RIGHT into the brick
    vy: 0,
  };

  const initialVx = state.ball.vx;
  frame(mockCtx, state);

  assert.ok(state.ball.vx < 0, `Ball should bounce LEFT (vx < 0), but got ${state.ball.vx}`);
});

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { createState, frame } from '../game/neon.js';

const mockCtx = {
  fillRect: () => {},
  arc: () => {},
  fill: () => {},
  fillText: () => {},
  beginPath: () => {},
};

test('Brick collision: ball should bounce ONLY vy off top of brick', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  state.ball = {
    x: brick.x + brick.w / 2,
    y: brick.y - 2,
    r: 7,
    vx: 100,
    vy: 200,
  };

  frame(mockCtx, state);

  assert.equal(state.ball.vy, -200, 'vy should flip');
  assert.equal(state.ball.vx, 100, 'vx should remain unchanged');
});

test('Brick collision: ball should bounce ONLY vx off side of brick', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  state.ball = {
    x: brick.x - 2,
    y: brick.y + brick.h / 2,
    r: 7,
    vx: 200,
    vy: 100,
  };

  frame(mockCtx, state);

  assert.equal(state.ball.vx, -200, 'vx should flip');
  assert.equal(state.ball.vy, 100, 'vy should remain unchanged');
});

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { createState, frame, BRICK_H, BRICK_W, BALL_R } from '../game/neon.js';

const mockCtx = {
  fillRect: () => {},
  arc: () => {},
  fill: () => {},
  fillText: () => {},
  beginPath: () => {},
};

test('D2: Sticking - Ball should be repositioned after collision', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  // Ball is deep inside the brick
  state.ball = {
    x: brick.x + brick.w / 2,
    y: brick.y + 2, 
    r: BALL_R,
    vx: 0,
    vy: 200,
  };

  frame(mockCtx, state);

  // It should be pushed out of the brick. 
  // Since it hit the top (vy > 0), it should be at y = brick.y - BALL_R
  assert.ok(state.ball.y - BALL_R <= brick.y, 'Ball should be repositioned to be outside the brick');
});

test('D3: Tunneling - Ball should not pass through brick at high speed', () => {
  const state = createState(10); // High speed
  const brick = state.bricks[0];

  // Ball is above the brick, moving fast enough to skip it in one frame
  // ballSpeed(10) = 1070. dt = 0.05. step = 53.5.
  state.ball = {
    x: brick.x + brick.w / 2,
    y: brick.y - 10, 
    r: BALL_R,
    vx: 0,
    vy: 1070,
  };

  // In the current implementation, frame() is called AFTER step().
  // But the "tunneling" happens in step(). 
  // Actually, the bug is that we use discrete collision in frame().

  // Simulate one step of movement
  const dt = 0.05;
  state.ball.y += state.ball.vy * dt; // y becomes brick.y - 10 + 53.5 = brick.y + 43.5
  // The ball has now passed the brick (h=20).

  frame(mockCtx, state);

  // If it tunneled, the brick is still alive.
  assert.equal(brick.alive, false, 'Brick should be destroyed even if ball tunneled through it');
});

test('D4: Double Inversion - Ball should not pass through seam of two bricks', () => {
  const state = createState(1);
  const brick1 = state.bricks[0];
  const brick2 = state.bricks[1];

  // Position ball so it overlaps both bricks on the same axis
  state.ball = {
    x: brick1.x + brick1.w - 2, // Overlapping right edge of brick 1 and left edge of brick 2
    y: brick1.y + brick1.h / 2,
    r: BALL_R,
    vx: 200,
    vy: 0,
  };

  frame(mockCtx, state);

  // If it flips vx twice, vx will be 200 again.
  assert.equal(state.ball.vx, -200, 'Ball should have vx inverted exactly once');
});

test('Face vs Coin: Corner hit should flip both axes', () => {
  const state = createState(1);
  const brick = state.bricks[0];

  // Ball hits the top-left corner
  state.ball = {
    x: brick.x + 2,
    y: brick.y + 2,
    r: BALL_R,
    vx: -100,
    vy: -100,
  };

  frame(mockCtx, state);

  assert.equal(state.ball.vx, 100, 'vx should flip');
  assert.equal(state.ball.vy, 100, 'vy should flip');
});

# To Fix: Ball through bricks

Le joueur rapporte : « la balle traverse les briques au lieu de rebondir ».

## D1 — Absence de rebond

- **Famille** : Face vs coin
- **Symptôme joueur** : la balle traverse les briques.
- **Cause** : `game/neon.js:198` — la détection de collision `collides()` est utilisée pour détruire la brique, mais aucune modification de `state.ball.vx` ou `state.ball.vy` n'est effectuée.
- **Invariant violé** : Toute collision avec un obstacle doit entraîner un changement de trajectoire.
- **Déclencheur** : Tout contact entre la balle et une brique active.
- **Attendu** : `vx` doit être inversé pour un impact latéral, `vy` pour un impact vertical.
- **Référence** : https://learnopengl.com/In-Practice/2D-Collision-Resolution — Inverser la composante de vitesse perpendiculaire à la face touchée.
- **Cas test** :
  ```js
  test('Brick collision: ball should bounce ONLY vy off top of brick', () => {
    const state = createState(1);
    const brick = state.bricks[0];
    state.ball = { x: brick.x + brick.w / 2, y: brick.y - 2, r: 7, vx: 100, vy: 200 };
    frame(mockCtx, state);
    assert.equal(state.ball.vy, -200);
    assert.equal(state.ball.vx, 100);
  });
  ```
- **Rouge aujourd'hui** : `AssertionError [ERR_ASSERTION]: vy should flip 200 !== -200`
- **Discrimine** : Refuse une correction qui n'inverse rien, ou qui inverse les deux axes systématiquement.
- **Vert quand** : Le test de rebond simple passe.
- **Révélé par** : Symptôme initial.

## D2 — Recouvrement (Sticking)

- **Famille** : Collant
- **Symptôme joueur** : la balle peut vibrer à l'intérieur d'une brique ou rester bloquée.
- **Cause** : Inversion de la vitesse sans repositionnement : la balle reste en collision au tour suivant et ré-inverse sa vitesse.
- **Invariant violé** : Après résolution, la balle doit être hors du rectangle de la brique.
- **Déclencheur** : Pénétration profonde d'une brique (ex: `ball.y + ball.r > brick.y` et `ball.y - ball.r < brick.y`).
- **Attendu** : `ball.y` repositionné à `brick.y - ball.r` (si hit top).
- **Référence** : https://gamedev.stackexchange.com/questions/407335/circle-vs-rectangle-collision-resolution — Repositionner l'objet sur le bord le plus proche.
- **Cas test** :
  ```js
  test('D2: Sticking - Ball should be repositioned after collision', () => {
    const state = createState(1);
    const brick = state.bricks[0];
    state.ball = { x: brick.x + brick.w / 2, y: brick.y + 2, r: 7, vx: 0, vy: 200 };
    frame(mockCtx, state);
    assert.ok(state.ball.y - 7 <= brick.y); // Simplifié pour l'instant, à resserrer
  });
  ```
- **Rouge aujourd'hui** : ( Sera rouge une fois D1 corrigé naïvement )
- **Discrimine** : Refuse une correction qui se contente de `vy = -vy`.
- **Vert quand** : La balle est instantanément éjectée de la brique.
- **Révélé par** : D1.

## D3 — Traversée (Tunneling)

- **Famille** : Traversée
- **Symptôme joueur** : la balle passe à travers une brique sans la toucher à haute vitesse.
- **Cause** : Détection discrète : si `ballSpeed * dt > (BRICK_H + 2 * BALL_R)`, la balle peut sauter par-dessus la brique.
- **Invariant violé** : Aucun obstacle ne doit être franchi sans rebond.
