// neon.test.js — PARTIAL coverage (on purpose).
//
// What is covered today: the collision primitive and a couple of physics
// bounces. What is NOT covered yet: score and combo (see ISSUES.md #5), nor
// level progression. This is a starting point for the testing work ahead, not
// a complete suite.
//
// Run: `node --test "game/**/*.test.js"`  (or `npm test`)

import { test } from 'node:test';
import assert from 'node:assert/strict';

import {
  collides,
  step,
  makeBricks,
  createState,
  BRICK_ROWS,
  BRICK_COLS,
  WIDTH,
  BALL_R,
} from './neon.js';

test('collides: clear overlap detected', () => {
  const ball = { x: 100, y: 100, r: 8 };
  const brick = { x: 90, y: 90, w: 40, h: 20 };
  assert.equal(collides(ball, brick), true);
});

test('collides: ball clearly away => no collision', () => {
  const ball = { x: 300, y: 300, r: 8 };
  const brick = { x: 90, y: 90, w: 40, h: 20 };
  assert.equal(collides(ball, brick), false);
});

test('collides: edge contact (radius) detected', () => {
  const ball = { x: 85, y: 100, r: 8 }; // right edge of the ball at 93 > 90
  const brick = { x: 90, y: 90, w: 40, h: 20 };
  assert.equal(collides(ball, brick), true);
});

test('step: bounce off the left wall', () => {
  const state = createState(1);
  state.ball = { x: 2, y: 200, r: 7, vx: -300, vy: 0 };
  step(state, 1 / 60);
  assert.ok(state.ball.vx > 0, 'horizontal velocity should flip to the right');
});

test('step: ball exiting through the bottom => lost', () => {
  const state = createState(1);
  state.ball = { x: 320, y: 500, r: 7, vx: 0, vy: 400 };
  const lost = step(state, 1 / 60);
  assert.equal(lost, true);
});

test('makeBricks: full, all-alive grid at start', () => {
  const bricks = makeBricks(1);
  assert.equal(bricks.length, BRICK_ROWS * BRICK_COLS);
  assert.ok(bricks.every((b) => b.alive));
  assert.ok(bricks.every((b) => b.x >= 0 && b.x + b.w <= WIDTH));
});

test('Brick collision: ball should bounce ONLY vy off top of brick', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  state.ball = { x: brick.x + brick.w / 2, y: brick.y - 2, r: 7, vx: 100, vy: 200 };
  step(state, 0.001);
  assert.equal(state.ball.vy, -200, 'vy should flip');
  assert.equal(state.ball.vx, 100, 'vx should remain unchanged');
});

test('Brick collision: ball should bounce ONLY vx off side of brick', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  state.ball = { x: brick.x - 2, y: brick.y + brick.h / 2, r: 7, vx: 200, vy: 100 };
  step(state, 0.001);
  assert.equal(state.ball.vx, -200, 'vx should flip');
  assert.equal(state.ball.vy, 100, 'vy should remain unchanged');
});

test('D2: Sticking - Ball should be repositioned after collision', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  state.ball = { x: brick.x + brick.w / 2, y: brick.y + 2, r: BALL_R, vx: 0, vy: 200 };
  step(state, 0.001);
  assert.ok(state.ball.y - BALL_R <= brick.y, 'Ball should be repositioned to be outside the brick');
});

test('D3: Tunneling - Ball should not pass through brick at high speed', () => {
  const state = createState(10);
  const brick = state.bricks[0];
  state.ball = { x: brick.x + brick.w / 2, y: brick.y - 10, r: 7, vx: 0, vy: 1070 };
  step(state, 0.05);
  assert.equal(brick.alive, false, 'Brick should be destroyed even if ball tunneled through it');
});

test('D4: Double Inversion - Ball should not pass through seam of two bricks', () => {
  const state = createState(1);
  const brick1 = state.bricks[0];
  const brick2 = state.bricks[1];
  state.ball = { x: brick1.x + brick1.w - 2, y: brick1.y + brick1.h / 2, r: 7, vx: 200, vy: 0 };
  step(state, 0.001);
  assert.equal(state.ball.vx, -200, 'Ball should have vx inverted exactly once');
});

test('Face vs Coin: Corner hit should flip both axes', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  state.ball = { x: brick.x + 2, y: brick.y + 2, r: 7, vx: -100, vy: -100 };
  step(state, 0.001);
  assert.equal(state.ball.vx, 100, 'vx should flip');
  assert.equal(state.ball.vy, 100, 'vy should flip');
});
